<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/DB.php';require_once __DIR__.'/../core/CacheStore.php';use Core\CacheStore;use Core\DB;$a=array('dry'=>false,'limit'=>0,'actors'=>6,'directors'=>3);$argv=isset($argv)?$argv:array();foreach(array_slice($argv,1)as $b){$b=(string)$b;if($b==='--dry'){$a['dry']=true;}elseif(strpos($b,'--limit=')===0){$a['limit']=max(0,(int)substr($b,8));}elseif(strpos($b,'--actors=')===0){$a['actors']=max(0,(int)substr($b,9));}elseif(strpos($b,'--directors=')===0){$a['directors']=max(0,(int)substr($b,12));}}try{$c=DB::pdo();$d='SELECT id, genres, extra FROM media_items ORDER BY id ASC';if($a['limit']>0){$d.=' LIMIT '.(int)$a['limit'];}$e=$c->query($d)->fetchAll();$f=$c->prepare('UPDATE media_items SET genres=? WHERE id=?');$g=0;$h=0;$i=0;foreach($e as $j){$g++;$k=CacheStore::peopleTags((string)$j['extra'],$a['directors'],$a['actors']);if(!$k){$i++;continue;}$l=json_decode((string)$j['genres'],true);if(!is_array($l)){$l=array();}$m=array_values(array_unique(array_merge($l,$k)));if(count($m)===count($l)){$i++;continue;}if(!$a['dry']){$f->execute(array(json_encode($m,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),(int)$j['id'],));}$h++;}if(!$a['dry']&&$h>0){CacheStore::invalidateTagCaches();}printf("[%s] 扫描 %d 条｜写入 %d 条｜跳过 %d 条（无人物数据或已含人物标签）\n",$a['dry']?'dry':'done',$g,$h,$i);if(!$a['dry']&&$h>0){echo"已推进标签缓存版本，首页标签云稍后自动包含演员/导演标签。\n";}exit(0);}catch(\Throwable $n){fwrite(STDERR,'回填失败：'.$n->getMessage()."\n");exit(1);}